import{_ as d,o as t,c as o,a2 as a}from"./chunks/framework.Dx-TCpNt.js";const m=JSON.parse('{"title":"カスタマイズ開発","description":"このセクションは、KomaYomi を使うだけでなく中身を変えたい人向けです。特定の雑誌に合わせたコマ検出プラグインを足す、フォルダー判定を調整する、書き出しレイアウトを配布する、アプリ本体を改造する——どれもここから始められます。記載したプロトコルとフィールドはすべてソースと突き合わせています…","frontmatter":{"description":"このセクションは、KomaYomi を使うだけでなく中身を変えたい人向けです。特定の雑誌に合わせたコマ検出プラグインを足す、フォルダー判定を調整する、書き出しレイアウトを配布する、アプリ本体を改造する——どれもここから始められます。記載したプロトコルとフィールドはすべてソースと突き合わせています…"},"headers":[],"relativePath":"ja/development/index.md","filePath":"ja/development/index.md","lastUpdated":1794794587000}'),c={name:"ja/development/index.md"};function r(s,e,i,l,n,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="カスタマイズ開発" tabindex="-1">カスタマイズ開発 <a class="header-anchor" href="#カスタマイズ開発" aria-label="Permalink to &quot;カスタマイズ開発&quot;">​</a></h1><p>このセクションは、KomaYomi を使うだけでなく中身を変えたい人向けです。特定の雑誌に合わせたコマ検出プラグインを足す、フォルダー判定を調整する、書き出しレイアウトを配布する、アプリ本体を改造する——どれもここから始められます。記載したプロトコルとフィールドはすべてソースと突き合わせています。食い違いを見つけたら、コードのほうが正しいと考えてください。</p><p>漫画を読んでノートを取るだけなら、<a href="/KomaYomi-docs/ja/guide/introduction">ガイド</a> から読むのが早いです。</p><h2 id="このセクションの構成" tabindex="-1">このセクションの構成 <a class="header-anchor" href="#このセクションの構成" aria-label="Permalink to &quot;このセクションの構成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ページ</th><th>答えること</th></tr></thead><tbody><tr><td>このページ</td><td>フロントエンド、サーバー、共有層の役割と、ローカル版だけが持つ機能。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/data-formats">データ形式</a></td><td>JSON エンベロープ、ページ文書、<code>library.json</code>、<code>.mnproj</code>、<code>.mntpl</code>、<code>.mnexp</code>、移行と未知フィールドの扱い。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/plugins">コマ分割プラグイン</a></td><td>プラグインの実際の契約、そのまま動く例、試し方、エラーコード。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/folder-rules">フォルダー判定ルール</a></td><td>プレースホルダー、省略可能な階層、ワイルドカード、<code>ignore</code>、<code>extensions</code>、よくある構成の完全な例。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/export-templates">エクスポートテンプレート</a></td><td>保存できるフィールド、完全な <code>.mnexp</code>、適用方法。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/build">ビルドとパッケージング</a></td><td>開発サーバー、本番ビルド、単体サーバー、Electron、Docker、静的オンライン版の違い。</td></tr><tr><td><a href="/KomaYomi-docs/ja/development/contributing">コントリビュート</a></td><td>ブランチとコミット規約、検査コマンド、最小の機能追加例。</td></tr></tbody></table><h2 id="リポジトリの構成" tabindex="-1">リポジトリの構成 <a class="header-anchor" href="#リポジトリの構成" aria-label="Permalink to &quot;リポジトリの構成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>パス</th><th>役割</th></tr></thead><tbody><tr><td><code>src/</code></td><td>React 18 のフロントエンド。ライブラリのサイドバー、コマ調整ワークベンチ、比較リーディング、ノート、エクスポートダイアログ、各種ダイアログ、多言語文言。</td></tr><tr><td><code>server/</code></td><td>Node の HTTP API とローカル機能一式。ライブラリ走査、コマ検出、レイアウトテンプレート、プラグイン、位置合わせプリセット、エクスポート、バックアップ、保存、履歴。</td></tr><tr><td><code>shared/</code></td><td>フロントとサーバーの共有部分。ドメイン型、JSON エンベロープと移行、コマ順序、Markdown 描画。</td></tr><tr><td><code>electron/</code></td><td>Electron メインプロセスとデータフォルダーの処理。</td></tr><tr><td><code>scripts/</code></td><td>バッチ CLI（<code>manga-cli.ts</code>）、サーバーバンドル、i18n スキャン、検出ベースライン。</td></tr><tr><td><code>plugins/</code></td><td>任意のコマ分割プラグイン。<code>data/plugins/</code> に置いてもかまいません。</td></tr><tr><td><code>docs/</code></td><td>この VitePress サイト。独自の <code>package.json</code> を持ちます。</td></tr><tr><td><code>raw/</code>、<code>data/</code>、<code>exports/</code></td><td>画像、JSON、生成物。いずれもコミットしません。</td></tr></tbody></table><h2 id="三つの層" tabindex="-1">三つの層 <a class="header-anchor" href="#三つの層" aria-label="Permalink to &quot;三つの層&quot;">​</a></h2><h3 id="フロントエンド-src" tabindex="-1">フロントエンド <code>src/</code> <a class="header-anchor" href="#フロントエンド-src" aria-label="Permalink to &quot;フロントエンド `src/`&quot;">​</a></h3><p>Vite でビルドする React のシングルページアプリです。<code>src/App.tsx</code> が全体の枠（上部バー、サイドバー、ステージ、ノート列、分割バー）を持ち、機能ごとの部品は <code>src/components/</code> にあります。バックエンドと話すのは <code>src/api.ts</code> だけで、すべて相対パス <code>/api/...</code> への <code>fetch</code> です。そのためフロントエンドは、Vite で動いているのか、単体サーバーなのか、Electron なのかを知りません。</p><p>ライブラリ、現在のページ文書、保存済みテンプレートといったサーバー側の状態は <code>src/api.ts</code> で読み、明示的に書き戻します。通常利用でブラウザー内のデータベースは使いません。</p><h3 id="サーバー-server" tabindex="-1">サーバー <code>server/</code> <a class="header-anchor" href="#サーバー-server" aria-label="Permalink to &quot;サーバー `server/`&quot;">​</a></h3><p>ルーティング関数は一つだけです。<code>server/app.ts</code> の <code>createMangaHandler({ rootDir })</code> が <code>pathname</code> と <code>method</code> を見て各モジュールへ渡します。同じハンドラーが三つのホストで動きます。</p><table tabindex="0"><thead><tr><th>ホスト</th><th>入口</th><th>アクセス方法</th></tr></thead><tbody><tr><td>開発・プレビュー</td><td><code>server/plugin.ts</code></td><td>Vite のミドルウェアとして <code>127.0.0.1:5173</code> に同居。別プロセスは不要。</td></tr><tr><td>単体サーバー / Docker</td><td><code>server/standalone.ts</code></td><td><code>npm start</code>、ポート <code>3921</code>。<code>RAW_DIR</code>、<code>DATA_DIR</code>、<code>EXPORT_DIR</code> で場所を変更。</td></tr><tr><td>デスクトップ</td><td><code>dist-server/app.mjs</code></td><td><code>scripts/build-server.mjs</code> が束ね、<code>electron/main.cjs</code> が読み込む。</td></tr></tbody></table><p>モジュールは意図的に狭く切っています。<code>library.ts</code> は走査とページのまとめ、<code>dirRules.ts</code> はパスパターンからページ記録、<code>detect.ts</code> は XY-cut 検出、<code>plugins.ts</code> はプラグイン実行、<code>layouts.ts</code> は宣言的グリッドの展開、<code>storage.ts</code> はページの読み書き、<code>schemaStore.ts</code> は移行と原子的な書き込み、<code>export.ts</code> と <code>exportDocx.ts</code> は文書生成、<code>project.ts</code> と <code>backup.ts</code> はプロジェクトと ZIP を担当します。</p><h3 id="共有層-shared" tabindex="-1">共有層 <code>shared/</code> <a class="header-anchor" href="#共有層-shared" aria-label="Permalink to &quot;共有層 `shared/`&quot;">​</a></h3><p><code>shared/</code> は Node 専用 API にも DOM にも依存できません。依存すると、どちらか一方の環境で使えなくなります。</p><table tabindex="0"><thead><tr><th>ファイル</th><th>内容</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td><code>PageDoc</code>、<code>Panel</code>、<code>Note</code>、<code>Annotation</code>、読み方向、エクスポート設定、ライブラリ型。</td></tr><tr><td><code>format.ts</code></td><td><code>$schema</code> / <code>schemaVersion</code> エンベロープ、形式ごとの検証、移行の振り分け、<code>preserveUnknown</code>。</td></tr><tr><td><code>migrations.ts</code></td><td>純粋な v0 → v1 移行。ディスクには触れません。</td></tr><tr><td><code>panelOrder.ts</code></td><td>表示・エクスポート・CLI が共有する読み順とグループ順。</td></tr><tr><td><code>markdown.ts</code></td><td>Markdown 描画。生の HTML はエスケープします。</td></tr><tr><td><code>schemas/*.json</code></td><td>読むための JSON Schema ミラー。実行時の正はコード側の検証器です。</td></tr></tbody></table><h2 id="リクエストの流れ" tabindex="-1">リクエストの流れ <a class="header-anchor" href="#リクエストの流れ" aria-label="Permalink to &quot;リクエストの流れ&quot;">​</a></h2><p><strong>ライブラリを読む。</strong> サイドバーが <code>GET /api/library</code> を呼びます。<code>server/app.ts</code> が受け取り、<code>server/library.ts</code> が <code>data/library.json</code> を読み、<code>server/dirRules.ts</code> でルールを解釈し、<code>raw/</code>（またはマップされたリモート先）をたどって 巻 → 章 → ページ にまとめて JSON を返します。書き込みはありません。</p><p><strong>ページを保存する。</strong> ワークベンチがページ文書全体を <code>PUT /api/page</code> で送ります。<code>server/app.ts</code> が基本構造を確認したあと、<code>server/storage.ts</code> の <code>writePageDoc</code> が次の順で処理します。</p><ol><li>新しいスキーマで書かれたファイルは拒否（<code>409</code>、<code>ERR_SCHEMA_TOO_NEW</code>）。</li><li>矩形、ノート、オフセット、id を正規化。</li><li><code>preserveUnknown</code> で前の版の未知フィールドを統合。</li><li><code>server/schemaStore.ts</code> 経由で原子的に書き込み。</li><li>呼び出し側が不要と言わない限り、版のスナップショットを記録。</li></ol><p><strong>コマを検出する。</strong> <code>POST /api/detect</code> は、そのページ・章・巻に紐づくレイアウトテンプレート、一致する最初のプラグイン、内蔵検出器の順に試します。結果は <code>detectSource</code> と <code>detectorVersion</code> と一緒に保存されるので、あとからどの矩形が誰のものか分かります。</p><h2 id="ローカル版だけの機能" tabindex="-1">ローカル版だけの機能 <a class="header-anchor" href="#ローカル版だけの機能" aria-label="Permalink to &quot;ローカル版だけの機能&quot;">​</a></h2><p>デスクトップ版とローカルサーバー版はファイルとプロセスに触れます。そのため次の機能は静的オンライン版にはありません。</p><table tabindex="0"><thead><tr><th>機能</th><th>ローカル Web / デスクトップ</th><th>静的オンライン版</th></tr></thead><tbody><tr><td><code>raw/</code> のフォルダー走査</td><td>あり</td><td>なし。ブラウザーはフォルダーツリーをたどれません。</td></tr><tr><td>自動コマ検出</td><td>あり</td><td>未移植。</td></tr><tr><td>レイアウトテンプレートとプラグイン</td><td>あり</td><td>なし。どちらもサーバープロセスで動きます。</td></tr><tr><td>WebDAV / ネットワーク保存と画像キャッシュ</td><td>あり</td><td>なし。</td></tr><tr><td>バックアップ ZIP、プロジェクト入出力</td><td>あり</td><td>プロジェクトは開けますが、フォルダーのバックアップはありません。</td></tr><tr><td>データの保存先</td><td>画像の隣の <code>data/</code></td><td>ブラウザーの IndexedDB</td></tr></tbody></table><p>静的オンライン版は別リポジトリで、まだ開発中です: <code>https://github.com/PayayaKamo/KomaYomi-online</code>。このリポジトリが作るのはローカル版だけです。共有範囲は<a href="/KomaYomi-docs/ja/development/build#静的オンライン版">ビルドとパッケージング</a>にまとめました。</p><h2 id="知っておくとよい約束事" tabindex="-1">知っておくとよい約束事 <a class="header-anchor" href="#知っておくとよい約束事" aria-label="Permalink to &quot;知っておくとよい約束事&quot;">​</a></h2><ul><li>サーバーは純粋な ESM TypeScript で、開発時は Node の型ストリップが直接実行します。import には <code>.ts</code> 拡張子が必要です。</li><li>データベースはありません。保存されるのはすべて JSON ファイルで、書き込みは原子的です。</li><li>利用者向けのメッセージは <code>server/messages/catalog.ts</code>、画面の文言は <code>src/i18n/</code> にあります。コンポーネントに中国語を直書きすると <code>npm run i18n:scan</code> が指摘します。</li><li>ドキュメントは三言語で同構成です。ページを足すときは <code>docs/&lt;page&gt;.md</code>、<code>docs/zh/&lt;page&gt;.md</code>、<code>docs/ja/&lt;page&gt;.md</code> をそろえ、<code>docs/.vitepress/config.mts</code> のナビとサイドバーにも追加します。</li></ul><h2 id="どこから読むか" tabindex="-1">どこから読むか <a class="header-anchor" href="#どこから読むか" aria-label="Permalink to &quot;どこから読むか&quot;">​</a></h2><ul><li>ディスク上のページの見つけ方を変える: <a href="/KomaYomi-docs/ja/development/folder-rules">フォルダー判定ルール</a>。</li><li>特定の雑誌だけ検出方法を変える: <a href="/KomaYomi-docs/ja/development/plugins">コマ分割プラグイン</a>。</li><li>KomaYomi のデータを読み書きするツールを作る: <a href="/KomaYomi-docs/ja/development/data-formats">データ形式</a>。</li><li>アプリ本体を変える: <a href="/KomaYomi-docs/ja/development/contributing">コントリビュート</a>。</li></ul>',31)])])}const b=d(c,[["render",r]]);export{m as __pageData,b as default};
